mapper.select:
select s.student_id as studentId, s.student_no as studentNo, s.name as name, s.major_id as majorId, s.entry_year as entryYear, s.college as college, s.cum_gpa as cumGpa, s.total_credits as totalCredits, coalesce(nullif(m.major_name_zh, ''), m.major_name_en, m.major_code, '') as majorName, m.major_code as majorCode from edu_student s left join edu_major m on m.major_id = s.major_id where s.del_flag = '0'
and s.entry_year = #{entryYear}
and s.major_id = #{majorId}
and (s.name like concat('%', #{keyword}, '%') or s.student_no like concat('%', #{keyword}, '%'))
order by s.student_no asc

select r.student_id as studentId, r.course_id as courseId, r.course_code as courseCode, coalesce(nullif(r.course_title, ''), c.title_zh, c.title_en, '') as courseTitle, r.grade as grade, r.score as score, coalesce(nullif(r.units, 0), c.credits, 0) as units, r.category as category, r.passed as passed, r.record_status as recordStatus, t.term_code as termCode, t.term_name as termName, t.academic_year as academicYear, t.term_index as termIndex from edu_course_record r left join edu_course c on c.course_id = r.course_id left join edu_term t on t.term_id = r.term_id where r.del_flag = '0'
and r.student_id = #{studentId}
order by t.term_code asc, r.record_id asc
